var APY=Object.assign(window.APY||{},{"既……又/也……":"jì …… yòu / yě ……","得了/不了":"de liǎo / bu liǎo","共享单车": "gòngxiǎng dānchē", "地铁站早餐车": "dìtiězhàn zǎocānchē", "便民送货": "biànmín sòng huò", "这是什么服务？": "Zhè shì shénme fúwù?", "怎么用？": "Zěnme yòng?", "给人们带来了什么方便？": "Gěi rénmen dàilái le shénme fāngbiàn?", "有没有不方便的地方？": "Yǒu méiyǒu bù fāngbiàn de dìfang?", "代表": "dàibiǎo", "既……又 / 也……": "jì …… yòu / yě ……", "来得及 / 来不及": "láidejí / láibují", "得了 / 不了": "de liǎo / bu liǎo","能够口头或书面表达不同出行方式及其优缺点。":"Nénggòu kǒutóu huò shūmiàn biǎodá bùtóng chūxíng fāngshì jí qí yōu-quēdiǎn.","了解中国城市中的便民服务。":"Liǎojiě Zhōngguó chéngshì zhōng de biànmín fúwù.","你帮助过别人吗？你是怎么提供帮助的？":"Nǐ bāngzhù guo biérén ma? Nǐ shì zěnme tígōng bāngzhù de?","我帮助过别人。上个星期，我在地铁站看到一位阿姨提着两个很重的袋子，我就帮她把袋子提到了站外。阿姨很感谢我。":"Wǒ bāngzhù guo biérén. Shàng ge xīngqī, wǒ zài dìtiězhàn kàndào yí wèi āyí tízhe liǎng ge hěn zhòng de dàizi, wǒ jiù bāng tā bǎ dàizi tídào le zhàn wài. Āyí hěn gǎnxiè wǒ.","你最常用的出行方式是什么？为什么？":"Nǐ zuì chángyòng de chūxíng fāngshì shì shénme? Wèi shénme?","我最常用的出行方式是骑电动车，因为电动车速度快，价格不高，充电也很方便。":"Wǒ zuì chángyòng de chūxíng fāngshì shì qí diàndòngchē, yīnwèi diàndòngchē sùdù kuài, jiàgé bù gāo, chōngdiàn yě hěn fāngbiàn.","停":"tíng","算":"suàn","剩":"shèng","联系":"liánxì","之间":"zhījiān","更加":"gèngjiā","距离":"jùlí","顺便":"shùnbiàn","流行":"liúxíng","力气":"lìqi","信号":"xìnhào","互相":"hùxiāng","免费":"miǎnfèi","往往":"wǎngwǎng","速度":"sùdù","客气":"kèqi","充电":"chōngdiàn","心情":"xīnqíng","麻烦":"máfan","省":"shěng","在地铁站，陈天中准备买票进站。":"Zài dìtiězhàn, Chén Tiānzhōng zhǔnbèi mǎi piào jìn zhàn.","陈天中的手机怎么了？":"Chén Tiānzhōng de shǒujī zěnme le?","丢了":"diū le","坏了":"huài le","停机了":"tíngjī le","忘带了":"wàng dài le","陈天中要去哪儿？":"Chén Tiānzhōng yào qù nǎr?","机场":"jīchǎng","手机店":"shǒujīdiàn","北京大学站":"Běijīng Dàxué Zhàn","在邻居家，白家月帮助邻居提东西。":"Zài línjū jiā, Bái Jiāyuè bāngzhù línjū tí dōngxi.","邻居提着很多什么？":"Línjū tízhe hěn duō shénme?","衣服":"yīfu","菜":"cài","水果":"shuǐguǒ","书":"shū","白家月为什么帮邻居提东西？":"Bái Jiāyuè wèi shénme bāng línjū tí dōngxi?","邻居病了":"línjū bìng le","邻居提不动":"línjū tí bu dòng","邻居让她帮":"línjū ràng tā bāng","邻居年纪大了":"línjū niánjì dà le","短距离出行的新选择":"Duǎn jùlí chūxíng de xīn xuǎnzé","白家月怎么去学校？":"Bái Jiāyuè zěnme qù xuéxiào?","走路":"zǒulù","骑自行车":"qí zìxíngchē","骑电动车":"qí diàndòngchē","最近陈天中打算买什么？":"Zuìjìn Chén Tiānzhōng dǎsuàn mǎi shénme?","手机":"shǒujī","自行车":"zìxíngchē","电动车":"diàndòngchē","运动鞋":"yùndòngxié","地铁站里的贴心服务":"Dìtiězhàn li de tiēxīn fúwù","根据课文，什么样的地铁站里最可能有早餐车？":"Gēnjù kèwén, shénme yàng de dìtiězhàn li zuì kěnéng yǒu zǎocānchē?","很大的":"hěn dà de","附近公司多的":"fùjìn gōngsī duō de","在学校旁边的":"zài xuéxiào pángbiān de","坐车乘客多的":"zuò chē chéngkè duō de","根据课文，人们在地铁站里最可能买到：":"Gēnjù kèwén, rénmen zài dìtiězhàn li zuì kěnéng mǎidào:","包子":"bāozi","雨衣":"yǔyī","雨伞":"yǔsǎn","地图":"dìtú","网":"wǎng","没有信号":"méiyǒu xìnhào","上不了":"shàng bu liǎo","别去超市了":"bié qù chāoshì le","外面":"wàimiàn","今天太晚了":"jīntiān tài wǎn le","再说":"zàishuō","还在下雨呢":"hái zài xià yǔ ne","好吃":"hǎochī","便宜":"piányi","这家饭馆的菜":"zhè jiā fànguǎn de cài","又":"yòu","既":"jì","咱们":"zánmen","中午12点的飞机":"zhōngwǔ shí'èr diǎn de fēijī","9点出发":"jiǔ diǎn chūfā","来得及吗":"láidejí ma","也让大家的心情":"yě ràng dàjiā de xīnqíng","人们的出行":"rénmen de chūxíng","方便了":"fāngbiàn le","这些小小的服务":"zhèxiē xiǎoxiǎo de fúwù","变得更加愉快":"biàn de gèngjiā yúkuài","……，再说……":"……, zàishuō ……","既……，又……":"jì ……, yòu ……","来得及":"láidejí","没来得及":"méi láidejí","既……又/也":"jì …… yòu / yě","安静":"ānjìng","漂亮":"piàoliang","方便":"fāngbiàn","安全":"ānquán","来不及":"láibují","我没带现金，手机没有信号，上不了网。":"Wǒ méi dài xiànjīn, shǒujī méiyǒu xìnhào, shàng bu liǎo wǎng.","联系方式":"liánxì fāngshì","对了，能不能告诉我你的联系方式？":"Duì le, néng bu néng gàosu wǒ nǐ de liánxì fāngshì?","没事儿，我年轻，力气大。":"Méi shìr, wǒ niánqīng, lìqi dà.","短距离出行时，骑自行车往往是人们常见的选择。":"Duǎn jùlí chūxíng shí, qí zìxíngchē wǎngwǎng shì rénmen chángjiàn de xuǎnzé.","电动车速度快，价格不高，充电也很方便，所以越来越流行。":"Diàndòngchē sùdù kuài, jiàgé bù gāo, chōngdiàn yě hěn fāngbiàn, suǒyǐ yuè lái yuè liúxíng.","乘客下班时可以顺便买花送给家人。":"Chéngkè xiàbān shí kěyǐ shùnbiàn mǎi huā sòng gěi jiārén.","小王今天早上起来晚了，没来得及吃早饭就去上班了。她坐地铁到了公司附近，想在地铁站买点儿吃的。小王选好早餐后，突然发现手机没电了，扫不了码。她正要把吃的放回去，一位乘客看到了，问她需不需要帮忙。小王把事情告诉了她，她就给小王买了一份早餐。小王非常感谢她，一直向她说“谢谢”。小王因为这件事，一天的心情都非常愉快。":"Xiǎo Wáng jīntiān zǎoshang qǐlai wǎn le, méi láidejí chī zǎofàn jiù qù shàngbān le. Tā zuò dìtiě dàole gōngsī fùjìn, xiǎng zài dìtiězhàn mǎi diǎnr chī de. Xiǎo Wáng xuǎnhǎo zǎocān hòu, tūrán fāxiàn shǒujī méi diàn le, sǎo bu liǎo mǎ. Tā zhèng yào bǎ chī de fàng huíqu, yí wèi chéngkè kàndào le, wèn tā xū bu xūyào bāngmáng. Xiǎo Wáng bǎ shìqing gàosu le tā, tā jiù gěi Xiǎo Wáng mǎi le yí fèn zǎocān. Xiǎo Wáng fēicháng gǎnxiè tā, yìzhí xiàng tā shuō “xièxie”. Xiǎo Wáng yīnwèi zhè jiàn shì, yì tiān de xīnqíng dōu fēicháng yúkuài.","啊，我的手机停机了！怎么办啊？":"Ā, wǒ de shǒujī tíngjī le! Zěnme bàn a?","我忘了交电话费，手机停机了。我没带现金，手机没有信号，上不了网，买不了地铁票了。":"Wǒ wàng le jiāo diànhuàfèi, shǒujī tíngjī le. Wǒ méi dài xiànjīn, shǒujī méiyǒu xìnhào, shàng bu liǎo wǎng, mǎi bu liǎo dìtiě piào le.","太感谢你了，我要去北京大学站。对了，能不能告诉我你的联系方式？我想把钱还给你。":"Tài gǎnxiè nǐ le, wǒ yào qù Běijīng Dàxué Zhàn. Duì le, néng bu néng gàosu wǒ nǐ de liánxì fāngshì? Wǒ xiǎng bǎ qián huán gěi nǐ.","阿姨，您提着这么多菜上楼啊，我帮您拿一些吧。":"Āyí, nín tízhe zhème duō cài shàng lóu a, wǒ bāng nín ná yìxiē ba.","没事儿，我年轻，力气大。您拿这个轻的袋子，重的袋子给我。":"Méi shìr, wǒ niánqīng, lìqi dà. Nín ná zhège qīng de dàizi, zhòng de dàizi gěi wǒ.","您太客气了。我提着这些东西就算锻炼身体了，再说邻居之间就是要互相帮助嘛。":"Nín tài kèqi le. Wǒ tízhe zhèxiē dōngxi jiù suàn duànliàn shēntǐ le, zàishuō línjū zhījiān jiùshì yào hùxiāng bāngzhù ma.","我最常用的出行方式":"Wǒ zuì chángyòng de chūxíng fāngshì","我最常用的出行方式是……":"Wǒ zuì chángyòng de chūxíng fāngshì shì ……","……既……，又……":"…… jì ……, yòu ……","不过……，再说……":"búguò ……, zàishuō ……","有时候来不及……，我就……":"yǒu shíhou láibují ……, wǒ jiù ……","你好，你看上去很着急，需要帮忙吗？":"Nǐ hǎo, nǐ kàn shàngqu hěn zháojí, xūyào bāngmáng ma?","你要去哪儿？我帮你买张票。":"Nǐ yào qù nǎr? Wǒ bāng nǐ mǎi zhāng piào.","别客气，很高兴能帮到你。":"Bié kèqi, hěn gāoxìng néng bāngdào nǐ.","谢谢你啊，姑娘。今天买的菜太多了，太重了，我真有点儿拿不动了。":"Xièxie nǐ a, gūniang. Jīntiān mǎi de cài tài duō le, tài zhòng le, wǒ zhēn yǒudiǎnr ná bu dòng le.","真是太感谢你了，麻烦你了。":"Zhēn shì tài gǎnxiè nǐ le, máfan nǐ le.","出行":"chūxíng","锻炼":"duànliàn","保护环境":"bǎohù huánjìng","价格":"jiàgé","省力气":"shěng lìqi","在城市里，人们出行的方式越来越多。短距离出行时，骑自行车往往是人们常见的选择。白家月就很喜欢骑车去学校，她觉得这样既方便，又能锻炼身体，还能保护环境。除了骑自行车，人们还会选择骑电动车。电动车速度快，价格不高，充电也很方便，所以越来越流行。陈天中平时也骑自行车，不过为了省力气，他最近打算买一辆电动车。":"Zài chéngshì li, rénmen chūxíng de fāngshì yuè lái yuè duō. Duǎn jùlí chūxíng shí, qí zìxíngchē wǎngwǎng shì rénmen chángjiàn de xuǎnzé. Bái Jiāyuè jiù hěn xǐhuan qí chē qù xuéxiào, tā juéde zhèyàng jì fāngbiàn, yòu néng duànliàn shēntǐ, hái néng bǎohù huánjìng. Chúle qí zìxíngchē, rénmen hái huì xuǎnzé qí diàndòngchē. Diàndòngchē sùdù kuài, jiàgé bù gāo, chōngdiàn yě hěn fāngbiàn, suǒyǐ yuè lái yuè liúxíng. Chén Tiānzhōng píngshí yě qí zìxíngchē, búguò wèile shěng lìqi, tā zuìjìn dǎsuàn mǎi yí liàng diàndòngchē.","来得及/来不及":"láidejí / láibují","重":"zhòng","提":"tí","这个箱子太重了，我一个人拿不动。":"Zhège xiāngzi tài zhòng le, wǒ yí ge rén ná bu dòng.","袋子里的东西很重，我帮你提吧。":"Dàizi li de dōngxi hěn zhòng, wǒ bāng nǐ tí ba.","收到朋友送的鲜花，她的心情非常好。":"Shōudào péngyou sòng de xiānhuā, tā de xīnqíng fēicháng hǎo.","今天天气很好，大家的心情都很愉快。":"Jīntiān tiānqì hěn hǎo, dàjiā de xīnqíng dōu hěn yúkuài.","阿姨提着很多菜回家。":"Āyí tízhe hěn duō cài huí jiā.","他提着两个袋子上楼了。":"Tā tízhe liǎng ge dàizi shàng lóu le.","我的城市里的便民服务":"Wǒ de chéngshì li de biànmín fúwù","不仅……也/还/而且":"bùjǐn …… yě / hái / érqiě","服务/方便":"fúwù / fāngbiàn","再说/顺便/来得及":"zàishuō / shùnbiàn / láidejí","能够听懂并交流日常生活中寻求或提供帮助的话题。":"Nénggòu tīngdǒng bìng jiāoliú rìcháng shēnghuó zhōng xúnqiú huò tígōng bāngzhù de huàtí."});
